// Astral ID_Continue character: MATHEMATICAL BOLD CAPITAL A (U+1D400)
const astralChar = "𝐀"; // U+1D400

// Manually create tokens where param is followed by text starting with astral char
// This simulates what happens when we force the param name to not include the astral char
const TokenData = (await import("../src/index.js")).TokenData;

// Create token data manually: param "id" followed by text "𝐀suffix"
const tokens = new TokenData([
  { type: "text", value: "/" },
  { type: "param", name: "id" },
  { type: "text", value: `${astralChar}suffix` }
]);

console.log("Tokens:", JSON.stringify(tokens, null, 2));

const stringified = stringify(tokens);
console.log("Stringified:", stringified);

// Now parse the stringified version to check round-trip
const { parse } = await import("../src/index.js");
const tokens2 = parse(stringified);
console.log("Re-parsed tokens:", JSON.stringify(tokens2, null, 2));

const stringified2 = stringify(tokens2);
console.log("Re-stringified:", stringified2);

if (stringified !== stringified2) {
  console.log("\nBUG CONFIRMED: Round-trip broken!");
  console.log(`Expected: ${stringified2}`);
  console.log(`Got: ${stringified}`);
} else {
  console.log("\nRound-trip OK");
}

// Also test the ID_CONTINUE regex behavior
const ID_CONTINUE = /^[$\u200c\u200d\p{ID_Continue}]$/u;
const firstChar = `${astralChar}suffix`[0];
console.log("\n--- Regex test ---");
console.log("astralChar:", astralChar);
