console.log("ID_CONTINUE.test(firstChar):", ID_CONTINUE.test(firstChar));
console.log("ID_CONTINUE.test(astralChar):", ID_CONTINUE.test(astralChar));

// Using spread operator
const [firstCodePoint] = [...`${astralChar}suffix`];
console.log("\nUsing spread:");
