import { parse, stringify, TokenData } from "../src/index.js";

// Various astral ID_Continue characters from different planes
const testCases = [
  { name: "U+1D400 (MATHEMATICAL BOLD A)", char: "𝐀" },
  { name: "U+1F600 (Emoji grinning face)", char: "😀" }, // Not ID_Continue
  { name: "U+10300 (OLD ITALIC LETTER A)", char: "𐌀" }, // ID_Continue in supplementary
  { name: "U+20000 (CJK Unified Ideograph)", char: "𠀀" }, // ID_Continue
];

let allPassed = true;

for (const tc of testCases) {
  const { name, char } = tc;
  console.log(`\nTest: ${name} (${char})`);

  // Create tokens: param "id" followed by text starting with astral char
  const tokens = new TokenData([
    { type: "text", value: "/" },
    { type: "param", name: "id" },
    { type: "text", value: `${char}rest` }
  ]);

  const stringified = stringify(tokens);
  const tokens2 = parse(stringified);
  const stringified2 = stringify(tokens2);

  // Check that the param name "id" is still just "id" (not "id<rest>")
  const paramName = tokens2.tokens.find(t => t.type === "param")?.name;

  if (paramName === "id") {
    console.log(`  ✓ Round-trip preserved param name correctly`);
  } else {
    console.log(`  ✗ Round-trip broke: param name became "${paramName}"`);
    allPassed = false;
  }
}

console.log("\n" + (allPassed ? "All tests passed!" : "Some tests failed!"));
EOF
